missing = []
existing = []

for name in input_list:
    slug = slugify(name)
    found = [c for c in cities if c.get('slug') == slug]
    
    if found:
        # Check if any is in mazowieckie
        maz = next((c for c in found if c.get('province') == 'mazowieckie'), None)
        if maz:
            existing.append(maz)
        else:
            missing.append({
                'name': name,
                'slug': slug,
                'found_matches': [
                    {'province': c.get('province'), 'district': c.get('district'), 'commune': c.get('commune')} 
                    for c in found
                ]
            })
    else:
        missing.append({
            'name': name,
            'slug': slug,
            'found_matches': []
        })

print("--- STATS ---")
print(f"Total input: {len(input_list)}")
print(f"Existing in Mazowieckie: {len(existing)}")
print(f"Missing (not in Mazowieckie): {len(missing)}")

print("\n--- MISSING (First 50) ---")
print(json.dumps(missing[:50], indent=2, ensure_ascii=False))

